for worker,ids in assignments.items():
 p=WORK/'results'/f'worker-{worker}.json';j=json.loads(p.read_text());rows=j['cases'];assert {r['case']for r in rows}=={f'B{i:03}'for i in ids};assert len(rows)==len(ids);raw_hashes[p.name]=sha(p)
 for r in rows:
  assert set(str(x).removesuffix('.png')for x in r['imagesInspected'])==set(key['imagesPerCase']),r['case']
  assert r['followUp'].lower()in['none','low','medium','high'];assert len(r['candidates'])<=3
  for c in r['candidates']:
   x,y=c['pixelCentre'];l,t,rr,b=c['pixelBox'];assert all(isinstance(v,(float,int))and math.isfinite(v)and 0<=v<=400 for v in[x,y,l,t,rr,b]);assert l<rr and t<b and l<=x<=rr and t<=y<=b,(r['case'],c);assert c['confidence'].lower()in['low','medium','high']
  text=json.dumps(r,ensure_ascii=False)
