for r in sorted(all_reviews,key=lambda r:r['case']):
 e=expected[r['case']];joined.append({'review':r,'evaluator':e})
 if not e['referencePointCrop']:continue
 refs=[]
 for ref in e['references']:
  distances=[]
  for n,c in enumerate(r['candidates']):
   x,y=c['pixelCentre'];l,t,rr,b=c['pixelBox'];distance=math.hypot(x-ref['pixelXY'][0],y-ref['pixelXY'][1])*.5;small=(rr-l)*(b-t)<=16000 and max(rr-l,b-t)<=200
   distances.append({'candidateIndex':n,'feature':c['feature'],'centreDistanceMetres':round(distance,2),'referencePointInsideBox':l<=ref['pixelXY'][0]<=rr and t<=ref['pixelXY'][1]<=b,'localizedBox':small,'near25m':distance<=25,'localizedNear25m':small and distance<=25})
  result={'case':r['case'],'patchId':e['patchId'],'cns':ref['cns'],'name':ref['name'],'type':ref['type'],'followUp':r['followUp'],'candidateCount':len(r['candidates']),'anyNear25m':any(c['near25m']for c in distances),'localizedNear25m':any(c['localizedNear25m']for c in distances),'nearestCentreMetres':min((c['centreDistanceMetres']for c in distances),default=None),'comparisons':distances};refs.append(result);by_record[ref['cns']].append(result)
 comparisons.append({'case':r['case'],'patchId':e['patchId'],'followUp':r['followUp'],'references':refs,'anyNear25m':any(x['anyNear25m']for x in refs),'localizedNear25m':any(x['localizedNear25m']for x in refs)})
assert len(comparisons)==8 and len(by_record)==5
