(OUT/'reviews-unblinded.json').write_text(json.dumps(joined,indent=2)+'\n');(OUT/'control-comparison.json').write_text(json.dumps(comparisons,indent=2)+'\n');(OUT/'summary.json').write_text(json.dumps(summary,indent=2)+'\n')
